<?php session_start(); require_once __DIR__ . '/db.php';  if (empty($_SESSION['admin_id'])) {     header('Location: login.php');     exit; }  $stmt = $pdo->query(   'SELECT a.application_id, a.full_name, a.email, a.phone, a.status, a.created_at,           c.course_name    FROM applications a    INNER JOIN courses c ON a.course_id = c.course_id    ORDER BY a.created_at DESC' ); $applications = $stmt->fetchAll();  function h(string $value): string {     return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); } ?> <!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin dashboard</title> <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"></head> <body><main class="container py-5"> <div class="d-flex justify-content-between align-items-center flex-wrap gap-2">   <h1>Applications dashboard</h1><a class="btn btn-outline-secondary" href="logout.php">Log out</a> </div> <p>Signed in as <?= h($_SESSION['admin_username'] ?? 'admin') ?>.</p> <div class="table-responsive"><table class="table table-striped"> <thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Course</th><th>Status</th><th>Date</th></t r></thead> <tbody> <?php foreach ($applications as $app): ?> <tr> <td><?= (int)$app['application_id'] ?></td> <td><?= h($app['full_name']) ?></td> <td><?= h($app['email']) ?></td> <td><?= h($app['phone']) ?></td> <td><?= h($app['course_name']) ?></td> <td><?= h($app['status']) ?></td> <td><?= h($app['created_at']) ?></td> </tr> <?php endforeach; ?> <?php if (!$applications): ?><tr><td colspan="7">No applications have been submitted yet.</td></tr><?php endif; ?> </tbody></table></div> </main></body></html> 